@ExtendWith(MockitoExtension.class)
class JwtUtilTest {

    @InjectMocks
    private JwtUtil jwtUtil;

    @Mock
    private Authentication authentication;

    @Mock
    private SecurityContext securityContext;

    private final String jwtSecret = "testSecret";
    private final int jwtExpirationMs = 86400000;

    @BeforeEach
    void setUp() {
        ReflectionTestUtils.setField(jwtUtil, "jwtSecret", jwtSecret);
        ReflectionTestUtils.setField(jwtUtil, "jwtExpirationMs", jwtExpirationMs);
    }

    @Test
    void generateJwtToken_ShouldReturnValidToken() {
        UserDetailsImpl userDetails = new UserDetailsImpl(1L, "testUser", "test@example.com", "password", null);
        when(authentication.getPrincipal()).thenReturn(userDetails);

        String token = jwtUtil.generateJwtToken(authentication);

        assertNotNull(token);
        assertTrue(token.length() > 0);
    }

    @Test
    void getUserNameFromJwtToken_ShouldReturnUsername() {
        String username = "testUser";
        String token = Jwts.builder()
                .setSubject(username)
                .setIssuedAt(new Date())
                .setExpiration(new Date((new Date()).getTime() + jwtExpirationMs))
                .signWith(SignatureAlgorithm.HS512, jwtSecret)
                .compact();

        String result = jwtUtil.getUserNameFromJwtToken(token);

        assertEquals(username, result);
    }

    @Test
    void validateJwtToken_ShouldReturnTrueForValidToken() {
        String token = Jwts.builder()
                .setSubject("testUser")
                .setIssuedAt(new Date())
                .setExpiration(new Date((new Date()).getTime() + jwtExpirationMs))
                .signWith(SignatureAlgorithm.HS512, jwtSecret)
                .compact();

        boolean isValid = jwtUtil.validateJwtToken(token);

        assertTrue(isValid);
    }

    @Test
    void validateJwtToken_ShouldReturnFalseForInvalidToken() {
        String invalidToken = "invalidToken";

        boolean isValid = jwtUtil.validateJwtToken(invalidToken);

        assertFalse(isValid);
    }

